import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { totpQrSvg } from "./totp-qr";

// Shape of Supabase Auth's SVGo output, as auth-js prefixes it.
const supabaseSvg =
  '<?xml version="1.0"?>\n<!-- Generated by SVGo -->\n<svg width="207" height="207"\n     xmlns="http://www.w3.org/2000/svg"\n     xmlns:xlink="http://www.w3.org/1999/xlink">\n<rect x="0" y="0" width="207" height="207" style="fill:white" />\n<rect x="12" y="12" width="3" height="3" style="fill:black" />\n</svg>\n';
const scalable =
  '<svg viewBox="0 0 207 207" width="207" height="207"\n     xmlns="http://www.w3.org/2000/svg"\n     xmlns:xlink="http://www.w3.org/1999/xlink">\n<rect x="0" y="0" width="207" height="207" style="fill:white" />\n<rect x="12" y="12" width="3" height="3" style="fill:black" />\n</svg>\n';
const withViewBox =
  '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 10 10"><path d="M0 0h1v1H0z"/></svg>';

void describe("totpQrSvg", () => {
  void it("reads Supabase's unencoded SVG and makes it scalable", () => {
    assert.equal(totpQrSvg(`data:image/svg+xml;utf-8,${supabaseSvg}`), scalable);
  });

  void it("reads percent-encoded and base64 SVG", () => {
    assert.equal(
      totpQrSvg(`data:image/svg+xml;utf-8,${encodeURIComponent(supabaseSvg)}`),
      scalable,
    );
    assert.equal(totpQrSvg(`data:image/svg+xml;base64,${btoa(withViewBox)}`), withViewBox);
  });

  void it("keeps raw SVG that contains a literal percent sign", () => {
    const svg = '<svg viewBox="0 0 1 1" width="100%"><rect width="1" height="1"/></svg>';
    assert.equal(totpQrSvg(`data:image/svg+xml;utf-8,${svg}`), svg);
  });

  void it("rejects missing, non-SVG or unsized input", () => {
    assert.equal(totpQrSvg(undefined), null);
    assert.equal(totpQrSvg("data:image/png;base64,AAAA"), null);
    assert.equal(totpQrSvg("data:image/svg+xml;utf-8,<script/>"), null);
    assert.equal(totpQrSvg("data:image/svg+xml;utf-8,<svg><rect/></svg>"), null);
  });
});
